import numpy as np


def min_max_dist_dim2_16() -> np.ndarray:
    """Return 16 points from a radius-two hexagonal lattice cluster."""

    excluded = {(0, -2), (1, -2), (2, -2)}
    points = []
    radius = 2
    for q in range(-radius, radius + 1):
        for r in range(-radius, radius + 1):
            if max(abs(q), abs(r), abs(q + r)) <= radius and (q, r) not in excluded:
                points.append((q + 0.5 * r, (np.sqrt(3.0) / 2.0) * r))
    return np.asarray(points, dtype=float)
